// Split by whitespace while preserving it, then process each word/part according to the specific casing rules.
export function titleCase(text) {
  if (typeof text !== 'string') throw new TypeError('Input must be a string');
  if (text === '') return '';

  const smallWords = new Set(['a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as']);

  const words = text.split(/(\s+)/);

  const processWord = (word, isFirst, isLast) => {
    if (!word) return word;

    // Rule 2: Hyphenated words
    if (word.includes('-')) {
      return word.split('-').map(part => processWord(part, false, false)).join('-');
    }

    // Rule 1: Acronyms
    if (/^[A-Z]{2,}$/.test(word)) return word;

    // Rule 4: Small words
    const lower = word.toLowerCase();
    if (smallWords.has(lower) && !isFirst && !isLast) {
      return lower;
    }

    // Rule 3: Capitalising
    return word.toLowerCase().replace(/([a-z])/, (match) => match.toUpperCase());
  };

  const nonWhitespaceIndices = [];
  for (let i = 0; i < words.length; i++) {
    if (!/^\s+$/.test(words[i]) && words[i] !== '') {
      nonWhitespaceIndices.push(i);
    }
  }

  if (nonWhitespaceIndices.length === 0) return text;

  const firstIdx = nonWhitespaceIndices[0];
  const lastIdx = nonWhitespaceIndices[nonWhitespaceIndices.length - 1];

  return words.map((w, i) => {
    if (!/^\s+$/.test(w) && w !== '') {
      return processWord(w, i === firstIdx, i === lastIdx);
    }
    return w;
  }).join('');
}

// Split the string, decode components, handle array logic, and store in a null-prototype object.
export function parseQuery(query) {
  if (typeof query !== 'string') throw new TypeError('Query must be a string');

  const result = Object.create(null);
  const raw = query.startsWith('?') ? query.slice(1) : query;
  if (!raw) return result;

  const pairs = raw.split('&');
  const decode = (str) => decodeURIComponent(str.replace(/\+/g, ' '));

  for (const pair of pairs) {
    if (!pair) continue;

    const eqIndex = pair.indexOf('=');
    let key, val;

    if (eqIndex === -1) {
      key = decode(pair);
      val = '';
    } else {
      key = decode(pair.slice(0, eqIndex));
      val = decode(pair.slice(eqIndex + 1));
    }

    const isArrayKey = key.endsWith('[]');
    const finalKey = isArrayKey ? key.slice(0, -2) : key;

    if (isArrayKey) {
      if (!(finalKey in result) || !Array.isArray(result[finalKey])) {
        result[finalKey] = Array.isArray(result[finalKey]) ? result[finalKey] : (finalKey in result ? [result[finalKey]] : []);
      }
      result[finalKey].push(val);
    } else {
      if (!(finalKey in result)) {
        result[finalKey] = val;
      } else if (Array.isArray(result[finalKey])) {
        result[finalKey].push(val);
      } else {
        result[finalKey] = [result[finalKey], val];
      }
    }
  }

  return result;
}

// Use a Map to store entries, relying on its insertion-order preservation to track usage (re-inserting keys moves them to the end).
export class LruCache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("Capacity must be an integer of at least 1");
    }
    this._capacity = capacity;
    this._map = new Map();
  }

  get(key) {
    if (!this._map.has(key)) return undefined;
    const value = this._map.get(key);
    this._map.delete(key);
    this._map.set(key, value);
    return value;
  }

  set(key, value) {
    if (this._map.has(key)) {
      this._map.delete(key);
    } else if (this._map.size >= this._capacity) {
      const firstKey = this._map.keys().next().value;
      this._map.delete(firstKey);
    }
    this._map.set(key, value);
    return this;
  }

  has(key) {
    return this._map.has(key);
  }

  delete(key) {
    return this._map.delete(key);
  }

  get size() {
    return this._map.size;
  }

  keys() {
    return Array.from(this._map.keys());
  }
}

// Use Array.from/slice for chunking and a recursive approach with Array.isArray for flattening.
export function chunk(items, size) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError('size must be an integer >= 1');
  }

  const result = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

export function flatten(items, depth = 1) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }
  if (depth !== Infinity && (!Number.isInteger(depth) || depth < 0)) {
    throw new RangeError('depth must be a non-negative integer or Infinity');
  }

  const result = [];
  for (const item of items) {
    if (depth > 0 && Array.isArray(item)) {
      result.push(...flatten(item, depth - 1));
    } else {
      result.push(item);
    }
  }
  return result;
}

// Iterate through the string character by character, tracking state to handle quoted fields, escaped quotes, and validation.
export function parseCsvLine(line) {
  if (typeof line !== 'string') throw new TypeError('Input must be a string');

  const fields = [];
  let i = 0;

  while (i <= line.length) {
    if (i < line.length && line[i] === '"') {
      // Quoted field
      let field = '';
      i++; // skip opening quote
      let closed = false;
      while (i < line.length) {
        if (line[i] === '"') {
          if (line[i + 1] === '"') {
            field += '"';
            i += 2;
          } else {
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }
      if (!closed) throw new RangeError('Unclosed quoted field');
      if (i < line.length && line[i] !== ',') throw new RangeError('Invalid character after closing quote');
      fields.push(field);
    } else {
      // Unquoted field
      let field = '';
      while (i < line.length && line[i] !== ',') {
        if (line[i] === '"') throw new RangeError('Quote inside unquoted field');
        field += line[i];
        i++;
      }
      fields.push(field);
    }

    if (i === line.length) {
      if (line.endsWith(',')) fields.push('');
      break;
    }
    i++; // skip comma
  }

  return fields;
}

// Use regex to insert underscores at boundaries, then normalize separators and lowercase the result.
export function toSnakeCase(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Input must be a string');
  }
  if (name === '') return '';

  return name
    // 1. Insert _ between lowercase/digit and uppercase
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    // 2. Insert _ before the last capital in a run of capitals followed by lowercase
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2')
    // 3. Replace spaces, tabs, and hyphens with _
    .replace(/[\s\t-]+/g, '_')
    // 4. Lowercase everything
    .toLowerCase()
    // 5. Collapse multiple underscores into one
    .replace(/_+/g, '_');
}

// Split text into words, then greedily pack them into lines, handling over-width words by breaking them into chunks.
export function wrapText(text, width) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  if (!Number.isInteger(width) || width < 1) {
    throw new RangeError('width must be an integer of at least 1');
  }

  const words = text.split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) return [];

  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    if (word.length > width) {
      // Finish current line if it exists
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }

      // Break the long word into chunks of 'width'
      for (let i = 0; i < word.length; i += width) {
        const chunk = word.slice(i, i + width);
        if (chunk.length === width) {
          lines.push(chunk);
        } else {
          currentLine = [chunk];
          currentLength = chunk.length;
        }
      }
    } else {
      // Check if word fits on current line
      const spaceNeeded = currentLine.length > 0 ? 1 : 0;
      if (currentLength + spaceNeeded + word.length <= width) {
        currentLine.push(word);
        currentLength += spaceNeeded + word.length;
      } else {
        // Start new line
        lines.push(currentLine.join(' '));
        currentLine = [word];
        currentLength = word.length;
      }
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

  return lines;
}

// Sort intervals by start time, then iterate and merge overlapping or touching intervals while validating inputs.
export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError("Input must be an array.");
  }

  const validated = intervals.map((interval) => {
    if (!Array.isArray(interval) || interval.length !== 2) {
      throw new TypeError("Each interval must be an array of two numbers.");
    }
    const [start, end] = interval;
    if (typeof start !== 'number' || typeof end !== 'number' || !Number.isFinite(start) || !Number.isFinite(end)) {
      throw new RangeError("Interval values must be finite numbers.");
    }
    if (start > end) {
      throw new RangeError("Start cannot be greater than end.");
    }
    return [start, end];
  });

  if (validated.length === 0) return [];

  // Sort by start time
  const sorted = [...validated].sort((a, b) => a[0] - b[0]);

  const result = [];
  let current = [...sorted[0]];

  for (let i = 1; i < sorted.length; i++) {
    const next = sorted[i];
    // If next starts before or exactly when current ends, they overlap/touch
    if (next[0] <= current[1]) {
      current[1] = Math.max(current[1], next[1]);
    } else {
      result.push(current);
      current = [...next];
    }
  }
  result.push(current);

  return result;
}

// Use a regex to extract components, validate the format, and sum the converted values while tracking seen units.
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (!trimmed) {
    throw new RangeError('Input is empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60000,
    h: 3600000,
    d: 86400000,
    w: 604800000
  };

  // Regex: matches number (digits, optional .digits) followed by unit
  // The whole string must be composed of these components separated by whitespace
  const componentRegex = /^(\d+(?:\.\d+)?)(ms|s|m|h|d|w)$/;
  const parts = trimmed.split(/\s+/);
  const seenUnits = new Set();
  let totalMs = 0;

  for (const part of parts) {
    const match = part.match(componentRegex);
    if (!match) {
      throw new RangeError('Invalid format');
    }

    const [, valueStr, unit] = match;
    if (seenUnits.has(unit)) {
      throw new RangeError('Duplicate unit');
    }

    seenUnits.add(unit);
    totalMs += parseFloat(valueStr) * units[unit];
  }

  return Math.round(totalMs);
}

// Normalize Unicode, replace non-alphanumeric sequences with hyphens, trim, and apply optional length constraints.
export function slugify(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const maxLength = options.maxLength;
  if (maxLength !== undefined && (!Number.isInteger(maxLength) || maxLength <= 0)) {
    throw new RangeError('maxLength must be a positive integer');
  }

  // 1. Normalize Unicode NFKD and remove combining marks
  let slug = text
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '');

  // 2. Lowercase
  slug = slug.toLowerCase();

  // 3. Replace non-alphanumeric with hyphens
  slug = slug.replace(/[^a-z0-9]+/g, '-');

  // 4. Remove hyphens from start and end
  slug = slug.replace(/^-+|-+$/g, '');

  // 6. Handle maxLength
  if (maxLength !== undefined && slug.length > maxLength) {
    slug = slug.substring(0, maxLength);
    // Remove trailing hyphens again after cutting
    slug = slug.replace(/-+$/g, '');
  }

  return slug;
}

