        field += line[i];
        i++;
      }
      result.push(field);
    }

    if (i === line.length) {
      // Check if line ends with a comma (trailing empty field)
      if (line.length > 0 && line[line.length - 1] === ',') {
        result.push('');
      }
      break;
    }
    i++; // skip comma
  }

  return result;
}

