// Recursively compare values by type, handling primitives, Dates, Maps, Sets, Arrays, and plain objects.
export function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) {
    return Number.isNaN(a) && Number.isNaN(b);
  }

  const protoA = Object.getPrototypeOf(a);
  const protoB = Object.getPrototypeOf(b);
  if (protoA !== protoB) return false;

  if (a instanceof Date) {
    return a.getTime() === b.getTime() || (isNaN(a.getTime()) && isNaN(b.getTime()));
  }

  if (a instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [key, val] of a) {
      if (!b.has(key) || !deepEqual(val, b.get(key))) return false;
    }
    return true;
  }

  if (a instanceof Set) {
    if (a.size !== b.size) return false;
    for (const val of a) {
      if (!b.has(val)) return false;
    }
    return true;
  }

  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  for (const key of keysA) {
    if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key])) {
      return false;
    }
  }

  return true;
}

// Sort intervals by start time, then iterate through them to merge overlapping or touching intervals into a new result array.
export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError("Input must be an array.");
  }

  const validated = intervals.map((interval) => {
    if (!Array.isArray(interval) || interval.length !== 2) {
      throw new TypeError("Each interval must be an array of two numbers.");
    }
    const [start, end] = interval;
    if (
      typeof start !== "number" ||
      typeof end !== "number" ||
      !Number.isFinite(start) ||
      !Number.isFinite(end)
    ) {
      throw new RangeError("Interval values must be finite numbers.");
    }
    if (start > end) {
      throw new RangeError("Start must be less than or equal to end.");
    }
    return [start, end];
  });

  if (validated.length === 0) return [];

  // Sort by start time (create a copy to avoid mutating original)
  const sorted = [...validated].sort((a, b) => a[0] - b[0]);

  const result = [];
  let current = [...sorted[0]];

  for (let i = 1; i < sorted.length; i++) {
    const next = sorted[i];
    // If next interval starts before or exactly when current ends, merge them
    if (next[0] <= current[1]) {
      current[1] = Math.max(current[1], next[1]);
    } else {
      result.push(current);
      current = [...next];
    }
  }
  result.push(current);

  return result;
}

// I will use Array.from and slice for chunking, and a recursive approach with Array.isArray for flattening.
export function chunk(items, size) {
  if (!Array.isArray(items)) {
    throw new TypeError('Input must be an array.');
  }
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError('Size must be an integer of at least 1.');
  }

  const result = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

export function flatten(items, depth = 1) {
  if (!Array.isArray(items)) {
    throw new TypeError('Input must be an array.');
  }
  if (depth !== Infinity && (!Number.isInteger(depth) || depth < 0)) {
    throw new RangeError('Depth must be a non-negative integer or Infinity.');
  }

  const flattenRecursive = (arr, currentDepth) => {
    let result = [];
    for (const item of arr) {
      if (currentDepth > 0 && Array.isArray(item)) {
        result.push(...flattenRecursive(item, currentDepth - 1));
      } else {
        result.push(item);
      }
    }
    return result;
  };

  return flattenRecursive(items, depth);
}

// Calculate the unit index based on the base, round the value, and handle unit promotion if rounding hits the base.
export function formatBytes(bytes, { binary = false, decimals = 1 } = {}) {
  if (typeof bytes !== 'number') throw new TypeError('Bytes must be a number');
  if (!Number.isFinite(bytes) || bytes < 0) throw new RangeError('Bytes must be a non-negative finite number');
  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 3) throw new RangeError('Decimals must be an integer between 0 and 3');

  const base = binary ? 1024 : 1000;
  const units = binary 
    ? ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'] 
    : ['B', 'kB', 'MB', 'GB', 'TB', 'PB'];

  bytes = Math.round(bytes);

  if (bytes < base) {
    return `${bytes} B`;
  }

  let i = 0;
  let value = bytes;
  while (value >= base && i < units.length - 1) {
    value /= base;
    i++;
  }

  const factor = Math.pow(10, decimals);
  value = Math.round(value * factor) / factor;

  if (value >= base && i < units.length - 1) {
    value /= base;
    i++;
  }

  return `${value.toFixed(decimals)} ${units[i]}`;
}

// Iterate through the items, resolve the key for each, and store them in a Map by appending to the array associated with that key.
export function groupBy(items, key) {
  if (!Array.isArray(items)) {
    throw new TypeError("items must be an array");
  }

  const isKeyFunction = typeof key === "function";
  const isKeyString = typeof key === "string";

  if (!isKeyFunction && !isKeyString) {
    throw new TypeError("key must be a string or a function");
  }

  const map = new Map();

  items.forEach((item, index) => {
    let groupKey;

    if (isKeyFunction) {
      groupKey = key(item, index);
    } else {
      groupKey = (item === null || item === undefined) ? undefined : item[key];
    }

    if (!map.has(groupKey)) {
      map.set(groupKey, []);
    }

    map.get(groupKey).push(item);
  });

  return map;
}

// Iterate through the string character by character, tracking state (quoted vs unquoted) to handle escaped quotes and field boundaries.
export function parseCsvLine(line) {
  if (typeof line !== 'string') throw new TypeError('Input must be a string');

  const fields = [];
  let currentField = '';
  let i = 0;

  while (i < line.length) {
    if (line[i] === '"') {
      // Quoted field
      i++;
      while (i < line.length) {
        if (line[i] === '"') {
          if (line[i + 1] === '"') {
            currentField += '"';
            i += 2;
          } else {
            // Closing quote found
            i++;
            if (i < line.length && line[i] !== ',') {
              throw new RangeError('Malformed CSV: content after closing quote');
            }
            break;
          }
        } else {
          currentField += line[i];
          i++;
        }
      }
      if (i > 0 && line[i - 1] !== '"') throw new RangeError('Malformed CSV: unclosed quote');
    } else {
      // Unquoted field
      while (i < line.length && line[i] !== ',') {
        if (line[i] === '"') throw new RangeError('Malformed CSV: quote in unquoted field');
        currentField += line[i];
        i++;
      }
    }

    fields.push(currentField);
    currentField = '';

    if (line[i] === ',') {
      i++;
      if (i === line.length) fields.push('');
    }
  }

  if (line === '') return [''];
  return fields;
}

// Split the string, decode components, handle array logic, and store in a null-prototype object.
export function parseQuery(query) {
  if (typeof query !== 'string') {
    throw new TypeError('Query must be a string');
  }

  const result = Object.create(null);
  const cleanQuery = query.startsWith('?') ? query.slice(1) : query;
  if (!cleanQuery) return result;

  const pairs = cleanQuery.split('&');

  for (const pair of pairs) {
    if (!pair) continue;

    const eqIndex = pair.indexOf('=');
    let rawKey, rawValue;

    if (eqIndex === -1) {
      rawKey = pair;
      rawValue = '';
    } else {
      rawKey = pair.slice(0, eqIndex);
      rawValue = pair.slice(eqIndex + 1);
    }

    const decode = (str) => {
      try {
        return decodeURIComponent(str.replace(/\+/g, ' '));
      } catch (e) {
        throw new RangeError('Malformed percent-encoding');
      }
    };

    let key = decode(rawKey);
    const value = decode(rawValue);
    let isArray = false;

    if (key.endsWith('[]')) {
      key = key.slice(0, -2);
      isArray = true;
    }

    if (!(key in result)) {
      result[key] = isArray ? [value] : value;
    } else {
      const existing = result[key];
      if (Array.isArray(existing)) {
        existing.push(value);
      } else {
        result[key] = [existing, value];
      }
    }
  }

  return result;
}

// Use a regex to extract components and a map to validate units and calculate total milliseconds.
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (!trimmed) {
    throw new RangeError('Input is empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000
  };

  // Regex: matches number (digits, optional . followed by digits) + unit
  // Ensures no leading/trailing junk by checking if the full string is consumed
  const componentRegex = /^(\d+(?:\.\d+)?)(ms|s|m|h|d|w)$/;
  const parts = trimmed.split(/\s+/);
  const seenUnits = new Set();
  let totalMs = 0;

  for (const part of parts) {
    const match = part.match(componentRegex);
    if (!match) {
      throw new RangeError('Invalid format');
    }

    const [, valueStr, unit] = match;
    if (seenUnits.has(unit)) {
