// Use regex to insert underscores at boundaries, then normalize separators and collapse duplicates.
export function toSnakeCase(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Input must be a string');
  }
  if (name === '') return '';

  return name
    // 1. Insert _ between lowercase/digit and uppercase
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    // 2. Insert _ before the last capital in a run followed by lowercase (e.g., XMLFile -> XML_File)
    .replace(/([A-Z])([A-Z])([a-z])/g, '$1_$2$3')
    // 3. Replace spaces, tabs, and hyphens with _
    .replace(/[\s\t-]+/g, '_')
    // 4. Convert to lowercase
    .toLowerCase()
    // 5. Collapse multiple underscores into one
    .replace(/_+/g, '_');
