// Split string by '&', decode components, handle array suffixes, and store in a null-prototype object.
export function parseQuery(query) {
  if (typeof query !== 'string') {
    throw new TypeError('Query must be a string');
  }

  const result = Object.create(null);
  const rawQuery = query.startsWith('?') ? query.slice(1) : query;

  if (!rawQuery) return result;

  const pairs = rawQuery.split('&');

  for (const pair of pairs) {
    if (!pair) continue;

    const index = pair.indexOf('=');
    const rawKey = index === -1 ? pair : pair.slice(0, index);
    const rawVal = index === -1 ? '' : pair.slice(index + 1);

    const decode = (str) => {
      try {
        return decodeURIComponent(str.replace(/\+/g, ' '));
      } catch (e) {
        throw new RangeError('Malformed percent-escape');
      }
    };

    let key = decode(rawKey);
    const value = decode(rawVal);
    let isArray = false;

    if (key.endsWith('[]')) {
      key = key.slice(0, -2);
      isArray = true;
    }

    if (!(key in result)) {
      result[key] = isArray ? [value] : value;
    } else {
      if (!Array.isArray(result[key])) {
        result[key] = [result[key]];
      }
      result[key].push(value);
    }
  }

  return result;
}

// Sort intervals by start time, then iterate through them to merge overlapping or touching intervals into a new result array.
export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError("Input must be an array.");
  }

  const validated = intervals.map((interval) => {
    if (!Array.isArray(interval) || interval.length !== 2) {
      throw new TypeError("Each interval must be an array of two numbers.");
    }
    const [start, end] = interval;
    if (typeof start !== "number" || typeof end !== "number" || !Number.isFinite(start) || !Number.isFinite(end)) {
      throw new RangeError("Interval values must be finite numbers.");
    }
    if (start > end) {
      throw new RangeError("Start must be less than or equal to end.");
    }
    return [start, end];
  });

  if (validated.length === 0) return [];

  // Sort by start time (copying to avoid mutation)
  const sorted = [...validated].sort((a, b) => a[0] - b[0]);

  const merged = [];
  let current = [...sorted[0]];

  for (let i = 1; i < sorted.length; i++) {
    const next = sorted[i];
    // If next starts before or at current end, merge them
    if (next[0] <= current[1]) {
      current[1] = Math.max(current[1], next[1]);
    } else {
      merged.push(current);
      current = [...next];
    }
  }
  merged.push(current);

  return merged;
}

// Parse version strings into components, compare numeric/alphanumeric segments, and handle prerelease precedence rules.
export function compareSemver(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') throw new TypeError('Inputs must be strings');

  const semverRegex = /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;

  const parse = (v) => {
    const match = v.match(semverRegex);
    if (!match) throw new RangeError('Invalid semver format');
    return {
      main: [Number(match[1]), Number(match[2]), Number(match[3])],
      pre: match[4] ? match[4].split('.') : null
    };
  };

  const v1 = parse(a);
  const v2 = parse(b);

  for (let i = 0; i < 3; i++) {
    if (v1.main[i] !== v2.main[i]) return v1.main[i] > v2.main[i] ? 1 : -1;
  }

  if (v1.pre === null && v2.pre !== null) return 1;
  if (v1.pre !== null && v2.pre === null) return -1;
  if (v1.pre === null && v2.pre === null) return 0;

  const len = Math.max(v1.pre.length, v2.pre.length);
  for (let i = 0; i < len; i++) {
    if (v1.pre[i] === undefined) return -1;
    if (v2.pre[i] === undefined) return 1;

    const isNum1 = /^\d+$/.test(v1.pre[i]);
    const isNum2 = /^\d+$/.test(v2.pre[i]);

    if (isNum1 && isNum2) {
      const n1 = BigInt(v1.pre[i]), n2 = BigInt(v2.pre[i]);
      if (n1 !== n2) return n1 > n2 ? 1 : -1;
    } else if (!isNum1 && !isNum2) {
      if (v1.pre[i] !== v2.pre[i]) return v1.pre[i] > v2.pre[i] ? 1 : -1;
    } else {
      return isNum1 ? -1 : 1;
    }
  }

  return 0;
}

// Recursively compare values by checking types, then specific structures for primitives, Dates, Maps, Sets, Arrays, and plain objects.
export function deepEqual(a, b) {
  if (a === b) return true;
  if (Number.isNaN(a) && Number.isNaN(b)) return true;

  const typeA = typeof a;
  const typeB = typeof b;

  if (typeA !== typeB || a === null || b === null) return false;

  if (typeA !== 'object') return false;

  // Handle Dates
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime() || (isNaN(a.getTime()) && isNaN(b.getTime()));
  }

  // Handle Arrays
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    return a.every((val, i) => deepEqual(val, b[i]));
  }

  // Handle Maps
  if (a instanceof Map && b instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [key, val] of a) {
      if (!b.has(key) || !deepEqual(val, b.get(key))) return false;
    }
    return true;
  }

  // Handle Sets
  if (a instanceof Set && b instanceof Set) {
    if (a.size !== b.size) return false;
    for (const val of a) {
      if (!b.has(val)) return false;
    }
    return true;
  }

  // Handle Plain Objects
  if (a.constructor === Object && b.constructor === Object) {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    for (const key of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key])) {
        return false;
      }
    }
    return true;
  }

  return false;
}

// Track tokens by updating the balance based on elapsed time since the last update, capping at capacity.
export class TokenBucket {
  constructor(capacity, refillPerSecond, startTimeMs = 0) {
    if (!Number.isInteger(capacity) || capacity <= 0) throw new RangeError("Capacity must be a positive integer");
    if (!Number.isFinite(refillPerSecond) || refillPerSecond <= 0) throw new RangeError("Refill rate must be a positive finite number");
    if (!Number.isFinite(startTimeMs)) throw new RangeError("Start time must be a finite number");

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.tokens = capacity;
    this.lastTime = startTimeMs;
  }

  _update(nowMs) {
    if (nowMs > this.lastTime) {
      const elapsedSeconds = (nowMs - this.lastTime) / 1000;
      this.tokens = Math.min(this.capacity, this.tokens + elapsedSeconds * this.refillPerSecond);
      this.lastTime = nowMs;
    }
  }

  available(nowMs) {
    if (!Number.isFinite(nowMs)) throw new RangeError("nowMs must be a finite number");
    this._update(nowMs);
    return this.tokens;
  }

  tryTake(count, nowMs) {
    if (!Number.isInteger(count) || count <= 0) throw new RangeError("Count must be a positive integer");
    if (!Number.isFinite(nowMs)) throw new RangeError("nowMs must be a finite number");

    this._update(nowMs);

    if (count > this.capacity) return false;
    if (this.tokens >= count) {
      this.tokens -= count;
      return true;
    }
    return false;
  }
}

// Use a Map to store entries, leveraging its property that insertion order is preserved to track recency.
export class LruCache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("Capacity must be an integer of at least 1");
    }
    this._capacity = capacity;
    this._cache = new Map();
  }

  get(key) {
    if (!this._cache.has(key)) return undefined;
    const value = this._cache.get(key);
    // Refresh position by deleting and re-inserting
    this._cache.delete(key);
    this._cache.set(key, value);
    return value;
  }

  set(key, value) {
    if (this._cache.has(key)) {
      this._cache.delete(key);
    } else if (this._cache.size >= this._capacity) {
      // Map.keys().next().value returns the oldest key
      const oldestKey = this._cache.keys().next().value;
      this._cache.delete(oldestKey);
    }
    this._cache.set(key, value);
    return this;
  }

  has(key) {
    return this._cache.has(key);
  }

  delete(key) {
    return this._cache.delete(key);
  }

  get size() {
    return this._cache.size;
  }

  keys() {
    return Array.from(this._cache.keys());
  }
}

// We maintain the current token count and the last timestamp, updating the count based on the elapsed time since the last call.
