  if (depth !== Infinity && (!Number.isInteger(depth) || depth < 0)) {
    throw new RangeError('Depth must be a non-negative integer or Infinity.');
  }

  function recursiveFlatten(arr, currentDepth) {
    let result = [];
    for (const item of arr) {
      if (currentDepth > 0 && Array.isArray(item)) {
        result.push(...recursiveFlatten(item, currentDepth - 1));
      } else {
        result.push(item);
      }
    }
    return result;
  }

  return recursiveFlatten(items, depth);
}

// Sort intervals by start time, then iterate through them to merge overlapping or touching intervals into a result array.
export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError("Input must be an array.");
  }

  const validated = intervals.map((interval) => {
    if (!Array.isArray(interval) || interval.length !== 2 || typeof interval[0] !== 'number' || typeof interval[1] !== 'number') {
      throw new TypeError("Each interval must be an array of two numbers.");
    }
    const [start, end] = interval;
    if (!Number.isFinite(start) || !Number.isFinite(end)) {
      throw new RangeError("Interval values must be finite numbers.");
    }
    if (start > end) {
      throw new RangeError("Start cannot be greater than end.");
    }
    return [start, end];
  });

  if (validated.length === 0) return [];

  const sorted = [...validated].sort((a, b) => a[0] - b[0]);
  const result = [];
  let current = [...sorted[0]];

  for (let i = 1; i < sorted.length; i++) {
    const next = sorted[i];
    if (next[0] <= current[1]) {
      current[1] = Math.max(current[1], next[1]);
    } else {
      result.push(current);
      current = [...next];
    }
  }
  result.push(current);

