}

// Split the text by whitespace while preserving it, then process each word/hyphenated part according to the specified rules.
export function titleCase(text) {
  if (typeof text !== 'string') throw new TypeError('Input must be a string');
  if (text === '') return '';

  const smallWords = new Set(['a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as']);

  const processWord = (word, isFirstOrLast) => {
    if (word.includes('-')) {
      return word.split('-').map(part => processWord(part, false)).join('-');
    }

    // Rule 1: Acronyms
    if (/^[A-Z]{2,}$/.test(word)) return word;

    // Rule 4: Small words
    const lower = word.toLowerCase();
    if (smallWords.has(lower) && !isFirstOrLast) return lower;

    // Rule 3: Capitalizing
    return word.replace(/([a-zA-Z])/, (match) => match.toUpperCase())
               .replace(/(?<=^[a-zA-Z])[a-zA-Z]+/, (match) => match.toLowerCase());
  };

  const parts = text.split(/(\s+)/);
  const words = parts.filter(p => !/^\s+$/.test(p) && p !== '');

  let wordIndex = 0;
  return parts.map(part => {
    if (/^\s+$/.test(part) || part === '') return part;
    const isFirstOrLast = (wordIndex === 0 || wordIndex === words.length - 1);
    wordIndex++;
    return processWord(part, isFirstOrLast);
  }).join('');
}

// Split text into words, then process each word by either appending to the current line or breaking it into chunks if it exceeds the width.
export function wrapText(text, width) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  if (!Number.isInteger(width) || width < 1) {
    throw new RangeError('width must be an integer of at least 1');
  }

  const words = text.split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) return [];

  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    if (word.length > width) {
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }

      let remaining = word;
      while (remaining.length > width) {
        lines.push(remaining.substring(0, width));
        remaining = remaining.substring(width);
      }
      currentLine.push(remaining);
      currentLength = remaining.length;
    } else {
      const spaceNeeded = currentLine.length > 0 ? 1 : 0;
      if (currentLength + spaceNeeded + word.length <= width) {
        currentLine.push(word);
        currentLength += spaceNeeded + word.length;
      } else {
        lines.push(currentLine.join(' '));
        currentLine = [word];
        currentLength = word.length;
      }
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

  return lines;
}

// Use a regex to extract components, validate the structure, and sum the converted values.
