    this._update(nowMs);
    return this.tokens;
  }

  tryTake(count, nowMs) {
    if (!Number.isInteger(count) || count <= 0) throw new RangeError('Count must be a positive integer');

    this._update(nowMs);

    if (count > this.capacity) return false;
    if (this.tokens >= count) {
      this.tokens -= count;
      return true;
    }
    return false;
  }
}

// Split text into words while preserving whitespace, then apply acronym, hyphen, and small-word rules to each segment.
