  while (i <= line.length) {
    let field = '';
    if (i < line.length && line[i] === '"') {
      // Quoted field
      i++;
      let closed = false;
      while (i < line.length) {
        if (line[i] === '"') {
          if (line[i + 1] === '"') {
            field += '"';
            i += 2;
          } else {
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }
      if (!closed) throw new RangeError('Unclosed quoted field');
      if (i < line.length && line[i] !== ',') throw new RangeError('Invalid character after closing quote');
    } else {
      // Unquoted field
      while (i < line.length && line[i] !== ',') {
        if (line[i] === '"') throw new RangeError('Quote inside unquoted field');
        field += line[i];
        i++;
      }
    }
    result.push(field);
    if (i === line.length && line.endsWith(',')) {
      result.push('');
    }
    i++;
  }

  return result;
}

// We track the current token count and the last timestamp, updating the balance based on the elapsed time since the last call.
export class TokenBucket {
  constructor(capacity, refillPerSecond, startTimeMs = 0) {
    if (!Number.isInteger(capacity) || capacity <= 0) throw new RangeError('capacity must be a positive integer');
    if (typeof refillPerSecond !== 'number' || !Number.isFinite(refillPerSecond) || refillPerSecond <= 0) throw new RangeError('refillPerSecond must be a positive finite number');
    if (typeof startTimeMs !== 'number' || !Number.isFinite(startTimeMs)) throw new RangeError('startTimeMs must be a finite number');

    this.capacity = capacity;
    this.refillPerMs = refillPerSecond / 1000;
    this.tokens = capacity;
    this.lastTime = startTimeMs;
  }

  _update(nowMs) {
    if (typeof nowMs !== 'number' || !Number.isFinite(nowMs)) throw new RangeError('nowMs must be a finite number');
    if (nowMs > this.lastTime) {
      const elapsed = nowMs - this.lastTime;
      this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.refillPerMs);
      this.lastTime = nowMs;
    }
  }

  available(nowMs) {
    this._update(nowMs);
    return this.tokens;
  }

  tryTake(count, nowMs) {
    if (!Number.isInteger(count) || count <= 0) throw new RangeError('count must be a positive integer');

    this._update(nowMs);

    if (count > this.capacity) return false;
    if (this.tokens >= count) {
      this.tokens -= count;
      return true;
    }
    return false;
  }
}

// Use a Map to store entries, relying on the fact that Map preserves insertion order to track usage.
export class LruCache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("Capacity must be an integer of at least 1");
    }
    this._capacity = capacity;
    this._cache = new Map();
  }

  get(key) {
    if (!this._cache.has(key)) return undefined;
    const value = this._cache.get(key);
    // Refresh position: delete and re-insert to move to the end (most recent)
    this._cache.delete(key);
    this._cache.set(key, value);
    return value;
  }

  set(key, value) {
    if (this._cache.has(key)) {
      this._cache.delete(key);
    } else if (this._cache.size >= this._capacity) {
      // Evict the first key (least recently used)
      const firstKey = this._cache.keys().next().value;
      this._cache.delete(firstKey);
    }
    this._cache.set(key, value);
    return this;
  }

  has(key) {
    return this._cache.has(key);
  }

  delete(key) {
    return this._cache.delete(key);
  }

  get size() {
    return this._cache.size;
  }

  keys() {
    return Array.from(this._cache.keys());
  }
}

// Use a regex to extract components and a map to validate units and calculate total milliseconds.
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (!trimmed) {
    throw new RangeError('Input cannot be empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000
  };

  const componentRegex = /^(\d+(?:\.\d+)?)(ms|s|m|h|d|w)$/;
  const parts = trimmed.split(/\s+/);
  const seenUnits = new Set();
  let totalMs = 0;

  for (const part of parts) {
    const match = part.match(componentRegex);
    if (!match) {
      throw new RangeError('Invalid format');
    }

    const [, valueStr, unit] = match;
    if (seenUnits.has(unit)) {
      throw new RangeError('Duplicate unit');
    }

    seenUnits.add(unit);
    totalMs += parseFloat(valueStr) * units[unit];
  }

  return Math.round(totalMs);
}

// Recursively compare values by type, handling primitives, Dates, Maps, Sets, Arrays, and plain objects.
export function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) {
    return Number.isNaN(a) && Number.isNaN(b);
  }

  const protoA = Object.getPrototypeOf(a);
  const protoB = Object.getPrototypeOf(b);
  if (protoA !== protoB) return false;

  if (a instanceof Date) {
    return a.getTime() === b.getTime() || (isNaN(a.getTime()) && isNaN(b.getTime()));
  }

  if (a instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [key, val] of a) {
      if (!b.has(key) || !deepEqual(val, b.get(key))) return false;
    }
    return true;
  }

  if (a instanceof Set) {
    if (a.size !== b.size) return false;
    for (const val of a) {
      if (!b.has(val)) return false;
    }
    return true;
  }

  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  // Plain objects
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  for (const key of keysA) {
    if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key])) {
      return false;
    }
  }

  return true;
}

// Parse versions into components, compare numeric parts, then compare prerelease identifiers according to SemVer rules.
export function compareSemver(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') throw new TypeError();

  const parse = (v) => {
    const regex = /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;
    const match = v.match(regex);
    if (!match) throw new RangeError();
    return {
      major: parseInt(match[1], 10),
      minor: parseInt(match[2], 10),
      patch: parseInt(match[3], 10),
      prerelease: match[4] ? match[4].split('.') : null
    };
  };

  const v1 = parse(a);
  const v2 = parse(b);

  const compareParts = (key) => v1[key] - v2[key];
  const major = compareParts('major');
  if (major !== 0) return major > 0 ? 1 : -1;
  const minor = compareParts('minor');
  if (minor !== 0) return minor > 0 ? 1 : -1;
  const patch = compareParts('patch');
  if (patch !== 0) return patch > 0 ? 1 : -1;

  if (v1.prerelease === null && v2.prerelease !== null) return 1;
  if (v1.prerelease !== null && v2.prerelease === null) return -1;
  if (v1.prerelease === null && v2.prerelease === null) return 0;

  const len = Math.min(v1.prerelease.length, v2.prerelease.length);
  for (let i = 0; i < len; i++) {
    const p1 = v1.prerelease[i];
    const p2 = v2.prerelease[i];
    const isN1 = /^\d+$/.test(p1);
    const isN2 = /^\d+$/.test(p2);

    if (isN1 && isN2) {
      const n1 = parseInt(p1, 10), n2 = parseInt(p2, 10);
      if (n1 !== n2) return n1 > n2 ? 1 : -1;
    } else if (!isN1 && !isN2) {
      if (p1 !== p2) return p1 > p2 ? 1 : -1;
    } else {
      return isN1 ? -1 : 1;
    }
  }

  return v1.prerelease.length === v2.prerelease.length ? 0 : (v1.prerelease.length > v2.prerelease.length ? 1 : -1);
}

// Iterate through the array, compute the key for each item, and push the item into the corresponding Map array.
export function groupBy(items, key) {
  if (!Array.isArray(items)) {
    throw new TypeError("items must be an array");
  }

  const isKeyFunction = typeof key === "function";
  const isKeyString = typeof key === "string";

  if (!isKeyFunction && !isKeyString) {
    throw new TypeError("key must be a string or a function");
  }

  const map = new Map();

  items.forEach((item, index) => {
    let groupKey;

    if (isKeyFunction) {
      groupKey = key(item, index);
    } else {
      groupKey = (item === null || item === undefined) ? undefined : item[key];
    }

    if (!map.has(groupKey)) {
      map.set(groupKey, []);
    }

    map.get(groupKey).push(item);
  });

  return map;
}

// Calculate the unit index based on the base, round the value, and handle unit promotion if rounding hits the base.
export function formatBytes(bytes, { binary = false, decimals = 1 } = {}) {
  if (typeof bytes !== 'number') throw new TypeError('bytes must be a number');
  if (!Number.isFinite(bytes) || bytes < 0) throw new RangeError('bytes must be a non-negative finite number');
  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 3) throw new RangeError('decimals must be an integer between 0 and 3');

  const base = binary ? 1024 : 1000;
  const units = binary 
    ? ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'] 
    : ['B', 'kB', 'MB', 'GB', 'TB', 'PB'];

  let roundedBytes = Math.round(bytes);

  if (roundedBytes < base) {
    return `${roundedBytes} B`;
  }

  let i = 0;
  let value = roundedBytes;
  while (value >= base && i < units.length - 1) {
    value /= base;
    i++;
  }

  // Round to specified decimals
  const factor = Math.pow(10, decimals);
  value = Math.round(value * factor) / factor;

  // Check if rounding pushed us to the next unit
  if (value >= base && i < units.length - 1) {
    value /= base;
    i++;
  }

  return `${value.toFixed(decimals)} ${units[i]}`;
}

