// Sort intervals by start time, then iterate through them, merging overlapping or adjacent intervals into a new result array.
export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError("Input must be an array.");
  }

  const validated = intervals.map((interval) => {
    if (!Array.isArray(interval) || interval.length !== 2) {
      throw new TypeError("Each interval must be an array of two numbers.");
    }
    const [start, end] = interval;
    if (typeof start !== 'number' || typeof end !== 'number' || !Number.isFinite(start) || !Number.isFinite(end)) {
      throw new RangeError("Interval values must be finite numbers.");
    }
    if (start > end) {
      throw new RangeError("Start cannot be greater than end.");
    }
    return [start, end];
  });

  if (validated.length === 0) return [];

  // Sort by start time (creating a copy to avoid mutation)
  const sorted = [...validated].sort((a, b) => a[0] - b[0]);

  const result = [];
  let current = [...sorted[0]];

  for (let i = 1; i < sorted.length; i++) {
    const next = sorted[i];
    // If next interval starts before or exactly at current end, merge them
    if (next[0] <= current[1]) {
      current[1] = Math.max(current[1], next[1]);
    } else {
      result.push(current);
      current = [...next];
    }
  }
  result.push(current);

  return result;
}

// Split text into words, then process each word by either appending to the current line or breaking it into chunks if it exceeds the width.
export function wrapText(text, width) {
  if (typeof text !== 'string') {
    throw new TypeError('Text must be a string');
  }
  if (!Number.isInteger(width) || width < 1) {
    throw new RangeError('Width must be an integer of at least 1');
  }

  const words = text.split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) return [];

  const lines = [];
  let currentLine = "";

  for (const word of words) {
    if (word.length > width) {
      // Finish current line if it exists
      if (currentLine.length > 0) {
        lines.push(currentLine);
        currentLine = "";
      }
      // Break the long word into chunks
      for (let i = 0; i < word.length; i += width) {
        const chunk = word.slice(i, i + width);
        if (chunk.length === width) {
          lines.push(chunk);
        } else {
          currentLine = chunk;
        }
      }
    } else {
      // Try to fit word in current line
      if (currentLine.length === 0) {
        currentLine = word;
      } else if (currentLine.length + 1 + word.length <= width) {
        currentLine += " " + word;
      } else {
        lines.push(currentLine);
        currentLine = word;
      }
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine);
  }

  return lines;
}

// Parse versions into components, compare numeric parts, then compare prerelease identifiers according to SemVer rules.
