  const v1 = parse(a);
  const v2 = parse(b);

  const compareParts = (p1, p2) => {
    if (p1 !== p2) return p1 > p2 ? 1 : -1;
    return 0;
  };

  if (v1.major !== v2.major) return compareParts(v1.major, v2.major);
  if (v1.minor !== v2.minor) return compareParts(v1.minor, v2.minor);
  if (v1.patch !== v2.patch) return compareParts(v1.patch, v2.patch);

  if (!v1.prerelease && !v2.prerelease) return 0;
  if (!v1.prerelease) return 1;
  if (!v2.prerelease) return -1;

  const len = Math.min(v1.prerelease.length, v2.prerelease.length);
  for (let i = 0; i < len; i++) {
    const p1 = v1.prerelease[i];
    const p2 = v2.prerelease[i];
    const n1 = /^\d+$/.test(p1);
    const n2 = /^\d+$/.test(p2);

    if (n1 && n2) {
      const diff = parseInt(p1, 10) - parseInt(p2, 10);
      if (diff !== 0) return diff > 0 ? 1 : -1;
    } else if (!n1 && !n2) {
      if (p1 !== p2) return p1 > p2 ? 1 : -1;
    } else {
      return n1 ? -1 : 1;
    }
  }

  return compareParts(v1.prerelease.length, v2.prerelease.length);
