// Split the text by whitespace, process each word/hyphenated part based on acronym, small-word, and capitalization rules, then reconstruct the string.
export function titleCase(text) {
  if (typeof text !== 'string') throw new TypeError('Input must be a string');
  if (text === '') return '';

  const smallWords = new Set(['a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as']);

  const processWord = (word, isFirstOrLast) => {
    if (word.includes('-')) {
      return word.split('-').map(part => processWord(part, false)).join('-');
    }

    // Rule 1: Acronyms
    if (/^[A-Z]{2,}$/.test(word)) return word;

    // Rule 4: Small words
    const lower = word.toLowerCase();
    if (!isFirstOrLast && smallWords.has(lower)) return lower;

    // Rule 3: Capitalizing
    return word.toLowerCase().replace(/([a-z])/, (match) => match.toUpperCase());
  };

  const words = text.split(/(\s+)/);
  const nonWhitespaceIndices = [];
  for (let i = 0; i < words.length; i++) {
    if (!/^\s+$/.test(words[i])) nonWhitespaceIndices.push(i);
  }

  if (nonWhitespaceIndices.length === 0) return text;

  const firstIdx = nonWhitespaceIndices[0];
  const lastIdx = nonWhitespaceIndices[nonWhitespaceIndices.length - 1];

  return words.map((word, i) => {
    if (/^\s+$/.test(word)) return word;
    return processWord(word, i === firstIdx || i === lastIdx);
  }).join('');
}

// Split text into words, then greedily pack them into lines, handling over-width words by slicing them into chunks.
export function wrapText(text, width) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  if (!Number.isInteger(width) || width < 1) {
    throw new RangeError('width must be an integer of at least 1');
  }

  const words = text.split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) return [];

  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (let word of words) {
    while (word.length > width) {
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }
      lines.push(word.substring(0, width));
      word = word.substring(width);
    }

    if (word.length > 0) {
      const spaceNeeded = currentLine.length > 0 ? 1 : 0;
      if (currentLength + spaceNeeded + word.length <= width) {
        currentLine.push(word);
        currentLength += spaceNeeded + word.length;
      } else {
        lines.push(currentLine.join(' '));
        currentLine = [word];
        currentLength = word.length;
      }
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

  return lines;
}

// Split by '&', handle decoding, manage array/scalar logic, and ensure no prototype.
export function parseQuery(query) {
