  for (const pair of pairs) {
    if (!pair) continue;
    const eqIndex = pair.indexOf('=');
    const rawKey = eqIndex === -1 ? pair : pair.slice(0, eqIndex);
    const rawVal = eqIndex === -1 ? '' : pair.slice(eqIndex + 1);

    let key = decode(rawKey);
    const val = decode(rawVal);
    let isArray = false;

    if (key.endsWith('[]')) {
      key = key.slice(0, -2);
      isArray = true;
    }

    if (!(key in result)) {
      result[key] = isArray ? [val] : val;
    } else {
      if (!Array.isArray(result[key])) {
        result[key] = [result[key]];
      }
      result[key].push(val);
    }
  }

  return result;
}

// Iterate through the string character by character, tracking state (quoted vs unquoted) to handle delimiters and escaped quotes.
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
