      i++;
      let closed = false;
      while (i < line.length) {
        if (line[i] === '"') {
          if (line[i + 1] === '"') {
            field += '"';
            i += 2;
          } else {
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }
      if (!closed) throw new RangeError('Unclosed quoted field');
      if (i < line.length && line[i] !== ',') {
