// Map values to canonical symbols and use a regex to validate the strict structure of Roman numerals.
const MAP = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
  [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
  [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']
];

export function toRoman(n) {
  if (typeof n !== 'number') throw new TypeError('Input must be a number');
  if (!Number.isInteger(n) || n < 1 || n > 3999) throw new RangeError('Input must be an integer between 1 and 3999');

  let result = '';
  let val = n;
  for (const [num, sym] of MAP) {
    while (val >= num) {
      result += sym;
      val -= num;
    }
  }
  return result;
}

export function fromRoman(text) {
  if (typeof text !== 'string') throw new TypeError('Input must be a string');

  // Regex ensures strict canonical form: M{0,3} (CM|CD|D?C{0,3}) (XC|XL|L?X{0,3}) (IX|IV|V?I{0,3})
  const regex = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

  if (text === '' || !regex.test(text)) throw new RangeError('Invalid canonical Roman numeral');

  let result = 0;
  let remaining = text;
  for (const [num, sym] of MAP) {
    while (remaining.startsWith(sym)) {
      result += num;
      remaining = remaining.slice(sym.length);
    }
  }

  if (remaining.length > 0 || result === 0) throw new RangeError('Invalid canonical Roman numeral');
  return result;
}

// Normalize Unicode, replace non-alphanumeric sequences with hyphens, trim, and apply length constraints.
export function slugify(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const { maxLength } = options;
  if (maxLength !== undefined && (!Number.isInteger(maxLength) || maxLength <= 0)) {
    throw new RangeError('maxLength must be a positive integer');
  }

  // 1. Normalize Unicode NFKD and remove combining marks
  let slug = text
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '');

  // 2. Lowercase
  slug = slug.toLowerCase();

  // 3. Replace non-alphanumeric with hyphens
  slug = slug.replace(/[^a-z0-9]+/g, '-');

  // 4. Remove hyphens from start and end
  slug = slug.replace(/^-+|-+$/g, '');

  // 6. Handle maxLength
  if (maxLength !== undefined && slug.length > maxLength) {
    slug = slug.substring(0, maxLength);
    // Remove trailing hyphens again after cutting
    slug = slug.replace(/-+$/g, '');
  }

  return slug;
}

// Split text into words, then greedily pack them into lines, handling over-width words by slicing them into chunks.
export function wrapText(text, width) {
  if (typeof text !== 'string') {
    throw new TypeError('Text must be a string');
  }
  if (!Number.isInteger(width) || width < 1) {
    throw new RangeError('Width must be an integer of at least 1');
  }

  const words = text.split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) return [];

  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (let word of words) {
    while (word.length > width) {
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }
      lines.push(word.substring(0, width));
      word = word.substring(width);
    }

    if (currentLine.length === 0) {
      currentLine.push(word);
      currentLength = word.length;
    } else if (currentLength + 1 + word.length <= width) {
      currentLine.push(word);
      currentLength += 1 + word.length;
    } else {
      lines.push(currentLine.join(' '));
      currentLine = [word];
      currentLength = word.length;
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

  return lines;
}

// Recursively compare values by type, handling primitives, Dates, Maps, Sets, Arrays, and plain objects.
export function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) {
    return Number.isNaN(a) && Number.isNaN(b);
  }

  const protoA = Object.getPrototypeOf(a);
  const protoB = Object.getPrototypeOf(b);
  if (protoA !== protoB) return false;

  if (a instanceof Date) {
    return a.getTime() === b.getTime() || (isNaN(a.getTime()) && isNaN(b.getTime()));
  }

  if (a instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [key, val] of a) {
      if (!b.has(key) || !deepEqual(val, b.get(key))) return false;
    }
    return true;
  }

  if (a instanceof Set) {
    if (a.size !== b.size) return false;
    for (const val of a) {
      if (!b.has(val)) return false;
    }
    return true;
  }

  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  for (const key of keysA) {
    if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key])) {
      return false;
    }
  }

  return true;
}

// Split the text by whitespace, process each word/hyphenated part based on acronym, small-word, and capitalization rules, then rejoin.
export function titleCase(text) {
  if (typeof text !== 'string') throw new TypeError('Input must be a string');
  if (text === '') return '';

  const smallWords = new Set(['a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as']);

  const processWord = (word, isFirstOrLast) => {
    if (word.includes('-')) {
      return word.split('-').map(part => processWord(part, false)).join('-');
    }

    // Rule 1: Acronyms
    if (/^[A-Z]{2,}$/.test(word)) return word;

    // Rule 4: Small words
    const lower = word.toLowerCase();
    if (smallWords.has(lower) && !isFirstOrLast) return lower;

    // Rule 3: Capitalizing
    return word.toLowerCase().replace(/[a-z]/, (match) => match.toUpperCase());
  };

  const parts = text.split(/(\s+)/);
  const words = parts.filter(p => !/^\s+$/.test(p));

  let wordIndex = 0;
  return parts.map(part => {
    if (/^\s+$/.test(part)) return part;
    const isFirstOrLast = (wordIndex === 0 || wordIndex === words.length - 1);
    const result = processWord(part, isFirstOrLast);
    wordIndex++;
    return result;
  }).join('');
}

// Iterate through items, resolve the key using the provided strategy, and collect them into a Map while preserving order.
export function groupBy(items, key) {
  if (!Array.isArray(items)) {
    throw new TypeError("items must be an array");
  }

  const isKeyFunction = typeof key === "function";
  const isKeyString = typeof key === "string";

  if (!isKeyFunction && !isKeyString) {
    throw new TypeError("key must be a string or a function");
  }

  const map = new Map();

  items.forEach((item, index) => {
    let groupKey;

    if (isKeyFunction) {
      groupKey = key(item, index);
    } else {
      // If item is null/undefined, property access throws, so we handle it
      groupKey = (item === null || item === undefined) ? undefined : item[key];
    }

    if (!map.has(groupKey)) {
      map.set(groupKey, []);
    }

    map.get(groupKey).push(item);
  });

  return map;
}

// Parse versions into components, compare numeric parts, then compare prerelease identifiers according to SemVer rules.
export function compareSemver(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') throw new TypeError('Inputs must be strings');

  const parse = (v) => {
    const regex = /^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;
    const match = v.match(regex);
    if (!match) throw new RangeError('Invalid version format');

    const [, major, minor, patch, pre] = match;
    const validate = (s) => !/^0\d+$/.test(s);
    if (!validate(major) || !validate(minor) || !validate(patch)) throw new RangeError('Leading zeros');

    return {
      nums: [parseInt(major, 10), parseInt(minor, 10), parseInt(patch, 10)],
      pre: pre ? pre.split('.') : null
    };
  };

  const v1 = parse(a);
  const v2 = parse(b);

  for (let i = 0; i < 3; i++) {
    if (v1.nums[i] !== v2.nums[i]) return v1.nums[i] > v2.nums[i] ? 1 : -1;
  }

  if (v1.pre === null && v2.pre === null) return 0;
  if (v1.pre === null) return 1;
  if (v2.pre === null) return -1;

  const len = Math.min(v1.pre.length, v2.pre.length);
  for (let i = 0; i < len; i++) {
    const p1 = v1.pre[i], p2 = v2.pre[i];
    const isN1 = /^\d+$/.test(p1), isN2 = /^\d+$/.test(p2);

    if (isN1 && isN2) {
      const n1 = BigInt(p1), n2 = BigInt(p2);
      if (n1 !== n2) return n1 > n2 ? 1 : -1;
    } else if (!isN1 && !isN2) {
      if (p1 !== p2) return p1 > p2 ? 1 : -1;
    } else {
      return isN1 ? -1 : 1;
    }
  }

  return v1.pre.length === v2.pre.length ? 0 : (v1.pre.length > v2.pre.length ? 1 : -1);
}

// Parse versions into components, compare numeric parts, then compare prerelease identifiers according to SemVer rules.
export function compareSemver(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') throw new TypeError('Inputs must be strings');

  const parse = (v) => {
    const regex = /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;
    const match = v.match(regex);
    if (!match) throw new RangeError('Invalid semver string');
    return {
      major: parseInt(match[1], 10),
      minor: parseInt(match[2], 10),
      patch: parseInt(match[3], 10),
      pre: match[4] ? match[4].split('.') : null
    };
  };

  const v1 = parse(a);
  const v2 = parse(b);

  const compareParts = (key) => v1[key] - v2[key];
  const res = compareParts('major') || compareParts('minor') || compareParts('patch');
  if (res !== 0) return res > 0 ? 1 : -1;

  if (!v1.pre && !v2.pre) return 0;
  if (!v1.pre) return 1;
  if (!v2.pre) return -1;

  for (let i = 0; i < Math.max(v1.pre.length, v2.pre.length); i++) {
    const p1 = v1.pre[i];
    const p2 = v2.pre[i];
    if (p1 === undefined) return -1;
    if (p2 === undefined) return 1;

    const isN1 = /^\d+$/.test(p1);
    const isN2 = /^\d+$/.test(p2);

    if (isN1 && isN2) {
      const diff = parseInt(p1, 10) - parseInt(p2, 10);
      if (diff !== 0) return diff > 0 ? 1 : -1;
    } else if (!isN1 && !isN2) {
      if (p1 !== p2) return p1 > p2 ? 1 : -1;
    } else {
      return isN1 ? -1 : 1;
    }
  }
  return 0;
}

// Map values to canonical Roman symbols and use a regex to validate the strict structure of the output.
const MAPPING = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
  [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
  [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']
];

const ROMAN_REGEX = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

export function toRoman(n) {
  if (typeof n !== 'number') throw new TypeError('Input must be a number');
  if (!Number.isInteger(n) || n < 1 || n > 3999) throw new RangeError('Input must be an integer between 1 and 3999');

  let result = '';
  let num = n;
  for (const [val, sym] of MAPPING) {
    while (num >= val) {
      result += sym;
      num -= val;
    }
  }
  return result;
}

export function fromRoman(text) {
  if (typeof text !== 'string') throw new TypeError('Input must be a string');
  if (text === '' || !ROMAN_REGEX.test(text)) throw new RangeError('Invalid canonical Roman numeral');

  let num = 0;
  let remaining = text;

  for (const [val, sym] of MAPPING) {
    while (remaining.startsWith(sym)) {
      num += val;
      remaining = remaining.slice(sym.length);
    }
  }

  if (remaining !== '' || num === 0) throw new RangeError('Invalid canonical Roman numeral');
  return num;
}

// Use regex to insert underscores at boundaries, then collapse sequences and normalize case.
export function toSnakeCase(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Input must be a string');
  }
  if (name === '') return '';

  return name
    // 1. Insert underscore between lowercase/digit and uppercase
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    // 2. Insert underscore before the last capital in a run followed by lowercase
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2')
    // 3. Replace spaces, tabs, and hyphens with underscores
    .replace(/[\s\t-]+/g, '_')
    // 4. Convert to lowercase
    .toLowerCase()
    // 5. Collapse multiple underscores into one
    .replace(/_+/g, '_');
}

// Normalize Unicode, replace non-alphanumeric sequences with hyphens, trim, and apply optional length constraints.
export function slugify(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const maxLength = options.maxLength;
  if (maxLength !== undefined && (!Number.isInteger(maxLength) || maxLength <= 0)) {
    throw new RangeError('maxLength must be a positive integer');
  }

  // 1. Normalize Unicode and remove combining marks
  let slug = text
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '');

  // 2. Lowercase
  slug = slug.toLowerCase();

  // 3. Replace non-alphanumeric with hyphens
  slug = slug.replace(/[^a-z0-9]+/g, '-');

  // 4. Remove hyphens from start and end
  slug = slug.replace(/^-+|-+$/g, '');

  // 6. Handle maxLength
  if (maxLength !== undefined && slug.length > maxLength) {
    slug = slug.substring(0, maxLength);
    // Remove trailing hyphens again after truncation
    slug = slug.replace(/-+$/g, '');
  }

  return slug;
}

// We track the current token count and the last timestamp, updating the balance based on elapsed time before each operation.
export class TokenBucket {
  constructor(capacity, refillPerSecond, startTimeMs = 0) {
    if (!Number.isInteger(capacity) || capacity <= 0) throw new RangeError("Capacity must be a positive integer");
    if (typeof refillPerSecond !== 'number' || !Number.isFinite(refillPerSecond) || refillPerSecond <= 0) throw new RangeError("Refill rate must be a positive finite number");
    if (typeof startTimeMs !== 'number' || !Number.isFinite(startTimeMs)) throw new RangeError("Start time must be a finite number");

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.tokens = capacity;
    this.lastTimeMs = startTimeMs;
  }

  _update(nowMs) {
    if (typeof nowMs !== 'number' || !Number.isFinite(nowMs)) throw new RangeError("Time must be a finite number");
    if (nowMs > this.lastTimeMs) {
      const elapsedSeconds = (nowMs - this.lastTimeMs) / 1000;
      this.tokens = Math.min(this.capacity, this.tokens + elapsedSeconds * this.refillPerSecond);
      this.lastTimeMs = nowMs;
    }
  }

  available(nowMs) {
    this._update(nowMs);
    return this.tokens;
  }

  tryTake(count, nowMs) {
    if (!Number.isInteger(count) || count <= 0) throw new RangeError("Count must be a positive integer");

    this._update(nowMs);

    if (count > this.capacity) return false;
    if (this.tokens >= count) {
      this.tokens -= count;
      return true;
    }
    return false;
  }
}

// Normalize Unicode, replace non-alphanumeric sequences with hyphens, trim, and apply optional length constraints.
export function slugify(text, options = {}) {
