}

// Calculate the unit index based on the base, round the value, and handle unit overflow.
export function formatBytes(bytes, { binary = false, decimals = 1 } = {}) {
  if (typeof bytes !== 'number') throw new TypeError('Bytes must be a number');
  if (bytes < 0 || !Number.isFinite(bytes)) throw new RangeError('Bytes must be a non-negative finite number');
  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 3) throw new RangeError('Decimals must be an integer between 0 and 3');

  const base = binary ? 1024 : 1000;
  const units = binary 
    ? ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'] 
    : ['B', 'kB', 'MB', 'GB', 'TB', 'PB'];

  bytes = Math.round(bytes);

  if (bytes < base) {
    return `${bytes} B`;
  }

  let i = 0;
  let value = bytes;
  while (value >= base && i < units.length - 1) {
    value /= base;
    i++;
  }

  // Handle rounding up to the next unit (e.g., 999.95 kB -> 1.0 MB)
  const factor = Math.pow(10, decimals);
  value = Math.round(value * factor) / factor;

  if (value >= base && i < units.length - 1) {
    value /= base;
    i++;
  }

  const formattedValue = decimals === 0 
    ? Math.round(value).toString() 
    : value.toFixed(decimals);

  return `${formattedValue} ${units[i]}`;
}

// Use a Map to store entries, leveraging its insertion-order property to track usage by deleting and re-inserting keys.
export class LruCache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("Capacity must be an integer of at least 1");
    }
    this._capacity = capacity;
    this._map = new Map();
  }

  get(key) {
    if (!this._map.has(key)) return undefined;
    const value = this._map.get(key);
    this._map.delete(key);
    this._map.set(key, value);
    return value;
  }

  set(key, value) {
    if (this._map.has(key)) {
      this._map.delete(key);
    } else if (this._map.size >= this._capacity) {
      const firstKey = this._map.keys().next().value;
      this._map.delete(firstKey);
    }
    this._map.set(key, value);
    return this;
  }

  has(key) {
    return this._map.has(key);
  }

  delete(key) {
    return this._map.delete(key);
  }

  get size() {
    return this._map.size;
  }

  keys() {
    return Array.from(this._map.keys());
  }
}

// Use a regex to extract components and a map to validate units and calculate total milliseconds.
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (!trimmed) {
    throw new RangeError('Input is empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000
  };

  // Regex: matches number (digits, optional .digits) followed by unit
  const componentRegex = /^(\d+(?:\.\d+)?)(ms|s|m|h|d|w)$/;
  const parts = trimmed.split(/\s+/);
  const seenUnits = new Set();
  let totalMs = 0;

  for (const part of parts) {
    const match = part.match(componentRegex);
    if (!match) {
      throw new RangeError(`Invalid component format: ${part}`);
    }

    const [, valueStr, unit] = match;
    if (seenUnits.has(unit)) {
      throw new RangeError(`Duplicate unit: ${unit}`);
    }

    seenUnits.add(unit);
    totalMs += parseFloat(valueStr) * units[unit];
  }

  return Math.round(totalMs);
}

// Recursively compare values by checking types, then specific structures for primitives, Dates, Maps, Sets, Arrays, and plain objects.
export function deepEqual(a, b) {
  if (a === b) return true;
  if (Number.isNaN(a) && Number.isNaN(b)) return true;

  const typeA = typeof a;
  const typeB = typeof b;

  if (typeA !== typeB || a === null || b === null) return false;

  if (typeA !== 'object') return false;

  // Handle Date
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime() || (isNaN(a.getTime()) && isNaN(b.getTime()));
  }

  // Handle Set
  if (a instanceof Set && b instanceof Set) {
    if (a.size !== b.size) return false;
    for (const val of a) if (!b.has(val)) return false;
    return true;
  }

  // Handle Map
  if (a instanceof Map && b instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [key, val] of a) {
      if (!b.has(key) || !deepEqual(val, b.get(key))) return false;
    }
    return true;
  }

  // Handle Array
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  // Handle Plain Objects
  if (a.constructor === Object && b.constructor === Object) {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    for (const key of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key])) {
        return false;
      }
    }
    return true;
  }

  return false;
}

