// I will implement chunk using a loop with slice and flatten using recursion with a depth-tracking mechanism.

export function chunk(items, size) {
  if (!Array.isArray(items)) {
    throw new TypeError('Input must be an array.');
  }
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError('Size must be an integer of at least 1.');
  }

  const result = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

export function flatten(items, depth = 1) {
  if (!Array.isArray(items)) {
    throw new TypeError('Input must be an array.');
  }
  if (depth !== Infinity && (!Number.isInteger(depth) || depth < 0)) {
    throw new RangeError('Depth must be a non-negative integer or Infinity.');
  }

  if (depth === 0) {
    return [...items];
  }

  const result = [];
  for (const item of items) {
    if (Array.isArray(item) && depth > 0) {
      result.push(...flatten(item, depth - 1));
    } else {
      result.push(item);
    }
  }
  return result;
}

// Iterate through the items, calculate the key for each, and store them in a Map by appending to arrays.
export function groupBy(items, key) {
  if (!Array.isArray(items)) {
    throw new TypeError("items must be an array");
  }

  const isKeyFunction = typeof key === "function";
  const isKeyString = typeof key === "string";

  if (!isKeyFunction && !isKeyString) {
    throw new TypeError("key must be a string or a function");
  }

  const map = new Map();

  items.forEach((item, index) => {
    let groupKey;

    if (isKeyFunction) {
      groupKey = key(item, index);
    } else {
      groupKey = (item === null || item === undefined) ? undefined : item[key];
    }

    if (!map.has(groupKey)) {
      map.set(groupKey, []);
    }

    map.get(groupKey).push(item);
  });

  return map;
}

// Use regex to insert underscores before camelCase boundaries and handle non-alphanumeric separators, then clean up redundant underscores.
export function toSnakeCase(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Input must be a string');
  }
  if (name === '') return '';

  return name
    // 1. Insert underscore between lowercase/digit and uppercase
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    // 2. Insert underscore before the last capital in a run followed by lowercase
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2')
    // 3. Replace spaces, tabs, hyphens, and existing underscores with a single underscore
    .replace(/[\s\t\-]+/g, '_')
    // 4. Convert to lowercase
    .toLowerCase()
    // 5. Collapse multiple underscores into one
    .replace(/_+/g, '_');
}
